INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531025-acct399', 'stk-guest', 'ACCT 399', 'info', '{"desc": "ممكن يكون كلامك صحيح\n\nلكن بالأخير هو مهندس وممكن يعمل في اي مكان او مكتب هندسي او محطات التحلية والمختبرات أو الكواليتي وهندسة الانتاج او السلامة .\n\nواعرف كثير هندسة كيميائية راحوا محاسبين وبعضهم في بنوك وغيرها رغم انها مو في تخصصهم . تسأله ليه يقلك أهم شيء وظيفة !\n\nجربت التدريب الصيفي مع ارامكو فعلاً عمل المهندس الكيميائي متعب جدا داخل البلانت والعمليات وكل شيء يعني العمل كله في الفيلد مع الأوبريشن تنكرف .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/183622/28", "user": "Guest", "ts": 1627511784000, "tid": 183622, "pn": 28}}', 1627511784000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1447036-acct399', 'stk-asrhc', 'ACCT 399', 'info', '{"desc": "بسم الله الرحمن الرحيم\nالسلام عليكم ورحمة الله وبركاته\n\nشركة كبرى بالرياض تعلن عن فتح باب التقديم للتدريب الصيفي وعن توفر فرص وظيفية للخريجين الجدد وذلك بالتخصصات التالية :\n( المالية - المحاسبة - ادارة الأعمال - الموارد البشرية )\n\nوعلى الراغبين بالتقدم إرسال السير الذاتية على البريد الإلكتروني hr@asrhc.com ،على ان يكون موضح بعنوان البريد الإلكتروني رغبة المتقدم : (تدريب صيفي ، توظيف) .\n\nوالله ولي التوفيق ،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/173021/1", "user": "ASRHC", "ts": 1461044533000, "tid": 173021, "pn": 1}}', 1461044533000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1442005-acct399', 'stk-user8581', 'ACCT 399', 'info', '{"desc": "ميفك كابيتال - برنامج التدريب الصيفي\nhttp://www.mefic.com.sa/ar/Careers/Application.aspx?VacancyID=c3d0997c-9207-4737-adbd-1039e1bed283\n\nhttp://www.mefic.com.sa/ar/about-mefic/overview\n\nتقدم ميفك كابيتال برنامج التدريب الصيفي و تدريب الطلبة للسعوديين في مختلف الإدارات.\nتقبل ميفك كابيتال عدد محدود وبشكل دوري من الطلبة في التخصصات التالية: المالية، الإستثمار، المحاسبةـ التسويق، الموارد البشرية، الإدارة العامة، الحاسب الآلي ونظم المعلومات، الرياضيات المالية، نظم المعلوماتيشترط في المتقدم أن يكون سعودي الجنسية وحاصل على معدل تراكمي مرتفع. يعتمد القبول على توفر شاغر في الإدارات حيث أن العدد الأقصى في كل إدارة يتراواح بين 1 إلى 2 طالب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/62", "user": "user8581", "ts": 1455440559000, "tid": 170272, "pn": 62}}', 1455440559000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509777-acct399', 'stk-ihajar', 'ACCT 399', 'info', '{"desc": "انا سويت مقابلة اليوم مع رئيس قسم الـ Accounting، وكانت الأسئلة تكنكال بحت. الزبدة تالي ودوني تبع قسم الـtreasury لاني اساسا تخصصي مالية. قالوا بيردون علي بكرة والشغل يبدأ يوم الأحد ١٩ مايو! أنا ما سألت بشكل مباشر اذا بعد هالتدريب في توظيف، بس اللي حسيته إن ممكن بعد فترة التدريب يكون في عروض لبعض المتميزين. انتوا شرايكم؟\nزوجي بعد قبلوه تدريب الـIndustrial Engineering بدون مقابلة، فما ندري كيف الوضع، نوافق أولا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rawabi/181478/7", "user": "Ihajar", "ts": 1557949159000, "tid": 181478, "pn": 7}}', 1557949159000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1322679-acct399', 'stk-taha_khaled', 'ACCT 399', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nأفدم لكم قائمة افضل شركات البترول والغاز في السعودية والتي يكون فيها التوظيف مفتوح\n\nعلى مدار العام\n\nوتطلب التخصصات التالية :-\n\n1- كلية الهندسة * يمكنك التدرب فيها من خلال التدريب الصيفي\n\n2- كلية علوم الارض * يمكنك التدرب فيها من خلال التدريب الصيفي\n\n3- كلية الحاسبات ( cs و it ) * يمكنك التدرب فيها من خلال التدريب الصيفي\n\n4- كلية الاقتصاد والادارة ( المحاسبة ، الموارد البشرية ، نظم المعلومات الادارية )\n\n5- كلية العلوم ( الفيزياء - والكيمياء ) * بعض الشركات تطلبها وليست كلها\n\n* من خلال بحثي وجدت ان هده التخصصات هي المطلوبة لدى شركات البترول والغاز\n\nقائمة الشركات :-\n\n- شركة ارامكو\n\n- شركة شلمبرجير\n\n- شركة بيكرهيوز\n\n- شركة هاليبرتون\n\n- شركة وذرفورد\n\n- شركة شيفرون\n\n- شركة بكتل\n\n- شركة اركاس\n\n- شركة مكامن\n\n- شركة الحوطي\n\n- شركة الحفر العربية\n\n- شركة اكسون موبيل\n\n- شركة الزيت العربية السعودية\n\n- شركة فلور\n\n- بترو رابغ\n\n- الجبيل الصناعية\n\n- ينبع الصناعية\n\nوهناك غيرها الكثير من الشركات وهدي افضلها\n\nتتميز هذه الشركات بقوة الراتب + البدلات\n\nفي الختام تقبلو مني خالص تحياتي\n\nمنقول من منتديات طلاب وطالبات جامعة الملك عبدالعزيز", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155834/1", "user": "taha_khaled", "ts": 1390762965000, "tid": 155834, "pn": 1}}', 1390762965000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
